{"code":"import random

def vary(example, rng):
    # Preserve the characteristic noisy field with a centered square two-colour object;
    # vary the size and the random speckle patterns.
    h = rng.randint(12, 24)
    w = rng.randint(12, 24)
    g = [[0 for _ in range(w)] for _ in range(h)]
    # sparse 1 noise outside, and a centered square containing 8/1 texture
    s = rng.randint(max(5, min(h,w)//3), max(6, min(h,w)*2//3))
    r0 = (h-s)//2; c0 = (w-s)//2
    for r in range(h):
        for c in range(w):
            if not (r0 <= r < r0+s and c0 <= c < c0+s):
                if rng.random() < .22: g[r][c] = 1
    for r in range(r0, r0+s):
        for c in range(c0, c0+s):
            g[r][c] = 8 if rng.random() < .53 else 1
    return g
"}

